func main() {
	in := bufio.NewReader(os.Stdin)
	var n, m int
	var p int64
	fmt.Fscan(in, &n, &m, &p)

	// Precompute factorials and inverse factorials up to n
	fact := make([]int64, n+1)
	ifact := make([]int64, n+1)
	fact[0] = 1
	for i := 1; i <= n; i++ {
		fact[i] = fact[i-1] * int64(i) % p
	}
	ifact[n] = modPow(fact[n], p-2, p)
	for i := n; i > 0; i-- {
		ifact[i-1] = ifact[i] * int64(i) % p
	}

	comb := func(n, k int) int64 {
		if k < 0 || k > n {
			return 0
		}
		return fact[n] * ifact[k] % p * ifact[n-k] % p
	}

	// dp[k][t]: number of ways to assign k participants to t computers (t<=k),
	// each participant chooses a computer in [1..t], and the induced process
	// (with fixed directions) occupies exactly t distinct computers.
	// This is independent of n; we will later multiply by ways to choose t computers among n.
	dp := make([][]int64, m+1)
	for i := range dp {
		dp[i] = make([]int64, m+1)
	}
	dp[0][0] = 1

	// For each participant, he chooses a computer among current t or possibly a new one (t+1),
	// and direction L/R (2 choices). But to ensure no one gets upset and exactly t occupied,
	// the combinatorics collapses to Stirling numbers of second kind times t! * 2^k.
	// However, we only need counts for all t; we can use recurrence:
	// dp[k+1][t] = dp[k][t]*t*2 + dp[k][t-1]*2
	for k := 0; k < m; k++ {
		for t := 0; t <= k; t++ {
			val := dp[k][t]
			if val == 0 {
				continue
			}
			// new participant joins existing t occupied computers
			dp[k+1][t] = (dp[k+1][t] + val*int64(t)*2) % p
			// or creates new occupied computer
			dp[k+1][t+1] = (dp[k+1][t+1] + val*2) % p
		}
	}

	// Now we need total madness sum. For symmetry, expected madness per configuration
	// with t occupied computers depends only on t and m, and total over computers is:
	// sum over pairs (assigned, final) distances. By symmetry, each pair of distinct
	// computers among t contributes equally. The total madness over all valid (a,b)
	// for fixed subset of t computers equals:
	// dp[m][t] * (t * (t-1) / 2) * E[distance between two distinct positions]
	// The expected distance over all pairs in subset of size t is:
	// (2 / (t*(t-1))) * sum_{i<j} (j-i).
	// sum_{i<j} (j-i) over positions 1..t is (t^3 - t)/6.
	// So average distance = (2*(t^3 - t)/(6*t*(t-1))) = (t+1)/3.
	// Total madness per configuration = m * average distance (each participant).
	// So total madness over all (a,b) for fixed subset = dp[m][t] * m * (t+1)/3.
	// Then multiply by number of subsets C(n,t).
	// Need modular inverse of 3.

	inv3 := modPow(3, p-2, p)

