	for t := 1; t <= m; t++ {
		if t > n {
			break
		}
		waysSubsets := comb(n, t)
		waysAssign := dp[m][t]
		avgDist := int64(t+1) * inv3 % p
		totalMadPerConfig := int64(m) * avgDist % p
		add := waysSubsets * waysAssign % p * totalMadPerConfig % p
		ans = (ans + add) % p
	}

	fmt.Println(ans % p)
}
