	pow2[0] = 1
	for i := 1; i <= m; i++ {
		pow2[i] = pow2[i-1] * 2 % p
	}

	// DP over number of occupied computers and total madness
	// dp[k] = number of ways to have k occupied computers after some participants
	// sumMad[k] = total madness over those ways
