		newSum := make([]int64, n+1)

		for k := 0; k <= n; k++ {
			if dp[k] == 0 {
				continue
			}
			// choose a target computer a_i
			for target := 1; target <= n; target++ {
				// number of free computers = n - k
				if n-k == 0 {
					continue
				}
				// For each direction L or R, participant may end up at some free computer.
