		dp[i] = make([]int64, m+1)
	}
	dp[0][0] = 1
	for len := 1; len <= n; len++ {
		dp[len][0] = 1
		for k := 1; k <= m && k <= len; k++ {
			// participant can enter from left or right
			// choose side and place at nearest free seat
			// recurrence: dp[len][k] = 2 * dp[len-1][k-1] + dp[len-1][k]
			dp[len][k] = (2*dp[len-1][k-1] + dp[len-1][k]) % mod
		}
	}

	// For each segment length, we also need total madness contribution
	// mad[len][k] = total madness over all ways seating k participants on len
	mad := make([][]int64, n+1)
	for i := 0; i <= n; i++ {
		mad[i] = make([]int64, m+1)
	}
	// base len=0: all zero
