				}
				term := C(seats, i) * modPow(int64(seats-i), int64(k), mod) % mod
				val += sign * term
				val %= mod
			}
			if val < 0 {
				val += mod
			}
			S[seats][k] = val
		}
	}

	// Precompute prefix sums of S for fast range sums over k
